import{_ as l,c as a,o as e,a4 as t}from"./chunks/framework.ChpgJYZx.js";const m=JSON.parse('{"title":"Vilinko Studio 付费服务协议","description":"","frontmatter":{},"headers":[],"relativePath":"agreement/pay.md","filePath":"agreement/pay.md"}'),o={name:"agreement/pay.md"};function r(h,i,n,u,d,s){return e(),a("div",null,i[0]||(i[0]=[t('<h1 id="vilinko-studio-付费服务协议" tabindex="-1">Vilinko Studio 付费服务协议 <a class="header-anchor" href="#vilinko-studio-付费服务协议" aria-label="Permalink to &quot;Vilinko Studio 付费服务协议&quot;">​</a></h1><p><a href="/en/agreement/pay.html">【English Version】</a></p><div class="tip custom-block"><p class="custom-block-title">版本</p><p>初版发布日期：2025 年 8 月 6 日</p><p>最近更新日期：2025 年 8 月 6 日</p></div><h2 id="一、协议范围与定义" tabindex="-1">一、协议范围与定义 <a class="header-anchor" href="#一、协议范围与定义" aria-label="Permalink to &quot;一、协议范围与定义&quot;">​</a></h2><ul><li>本协议是您（用户）与 Vilinko Studio（以下简称&quot;我们&quot;）之间关于使用 Vilinko Studio 提供的付费信息技术工具及相关服务（以下简称&quot;付费服务&quot;）所订立的具有法律效力的协议。</li><li>付费服务包括但不限于：&quot;LightFrame&quot;软件定制服务（详情参见 <a href="/docs/lightframe/index.html">LightFrame</a>、高级会员服务、增值功能模块、专属技术支持等。</li><li>本协议是《Vilinko Studio 软件服务协议》的补充协议，与主协议具有同等法律效力。若本协议与主协议内容不一致，优先适用本协议。</li><li>您购买或使用任何付费服务，即视为您已阅读、理解并同意本协议的全部条款。</li></ul><h2 id="二、付费服务内容与价格" tabindex="-1">二、付费服务内容与价格 <a class="header-anchor" href="#二、付费服务内容与价格" aria-label="Permalink to &quot;二、付费服务内容与价格&quot;">​</a></h2><ul><li>具体付费服务内容、功能说明、服务期限及对应价格以服务购买页面或相关服务说明文档为准。</li><li>我们有权根据市场情况调整付费服务的价格及内容，但已购买的服务不受调整影响。</li><li>&quot;LightFrame&quot;定制服务内容及价格以 <a href="/docs/lightframe/index.html">LightFrame</a> 页面公布的信息为准，如需个性化定制超出标准范围的服务，双方另行协商确定。</li></ul><h2 id="三、服务购买与支付" tabindex="-1">三、服务购买与支付 <a class="header-anchor" href="#三、服务购买与支付" aria-label="Permalink to &quot;三、服务购买与支付&quot;">​</a></h2><ul><li>您可通过我们官方网站、客户端或指定第三方平台（包括但不限于爱发电平台）购买付费服务。</li><li>支付方式以购买页面展示的方式为准，您应按照选定的支付方式完成付款。</li><li>付款成功后，我们将在合理时间内为您开通相应的付费服务，服务期限自开通之日起计算。</li><li>如因支付系统故障导致付款成功但服务未开通，您可联系客服处理，我们将在核实后及时解决。</li></ul><h2 id="四、服务使用规范" tabindex="-1">四、服务使用规范 <a class="header-anchor" href="#四、服务使用规范" aria-label="Permalink to &quot;四、服务使用规范&quot;">​</a></h2><ul><li>您购买的付费服务仅限于您本人或您所代表的合法实体使用，不得转让、出租、出借或分享给任何第三方，除非获得我们的书面许可。</li><li>您不得利用付费服务进行任何违法违规活动，不得侵犯任何第三方的合法权益。</li><li>对于&quot;LightFrame&quot;定制服务，您应按照 <a href="/docs/lightframe/index.html">LightFrame</a> 中的要求提供必要的素材和信息，因您提供的信息不完整或不准确导致的定制延误或效果不符，我们不承担责任。</li></ul><h2 id="五、退款政策" tabindex="-1">五、退款政策 <a class="header-anchor" href="#五、退款政策" aria-label="Permalink to &quot;五、退款政策&quot;">​</a></h2><ul><li>除以下情况外，付费服务一旦购买，不支持退款： <ul><li>付费服务存在重大功能缺陷，且我们在合理期限内无法修复，影响核心使用的；</li><li>因我们原因导致您无法使用已购买的付费服务，且无法提供替代方案的；</li><li>法律法规另有规定的。</li></ul></li><li>申请退款需在发现问题后7个工作日内联系客服，提供相关证明材料，我们将在15个工作日内审核并处理。</li><li>通过第三方平台（如爱发电）购买的服务，退款政策可能同时适用该平台的相关规定。</li></ul><h2 id="六、服务变更与终止" tabindex="-1">六、服务变更与终止 <a class="header-anchor" href="#六、服务变更与终止" aria-label="Permalink to &quot;六、服务变更与终止&quot;">​</a></h2><ul><li>我们有权对付费服务进行必要的更新和优化，如涉及服务内容重大变更，将提前7天通过官方渠道通知您。</li><li>如您违反本协议或主协议的规定，我们有权暂停或终止向您提供付费服务，且不退还已支付的费用。</li><li>服务期限届满后，如您未续费，付费服务将自动终止，您将无法继续使用相应的付费功能，但免费服务不受影响。</li></ul><h2 id="七、知识产权保护" tabindex="-1">七、知识产权保护 <a class="header-anchor" href="#七、知识产权保护" aria-label="Permalink to &quot;七、知识产权保护&quot;">​</a></h2><ul><li>我们拥有所有付费服务及相关软件、代码、内容的全部知识产权，除非另有明确声明。</li><li>部分软件及代码在GitHub平台开源，遵循相应的开源协议（如MIT、GPL等），您的使用需同时遵守相关开源协议的规定。</li><li>对于&quot;LightFrame&quot;定制服务的输出成果，如无特别约定，您仅获得该成果的使用权，相关知识产权仍归我们所有。如需获得知识产权转让，需另行签署协议并支付相应费用。</li><li>您不得对付费服务相关的软件、代码进行反向工程、反向编译、反汇编或其他类似行为，不得擅自修改、复制、传播或衍生创作。</li><li>您在使用付费服务过程中上传或创作的内容，其知识产权归您所有，但您授予我们必要的使用权以提供服务。</li></ul><h2 id="八、免责声明" tabindex="-1">八、免责声明 <a class="header-anchor" href="#八、免责声明" aria-label="Permalink to &quot;八、免责声明&quot;">​</a></h2><ul><li>付费服务按&quot;现状&quot;提供，我们不保证服务完全无瑕疵或不间断，但会尽力保障服务的稳定性。</li><li>因不可抗力、第三方服务故障、您的设备或网络问题等原因导致服务中断或无法使用，我们不承担责任，但会尽力协助解决。</li><li>您理解并同意，使用付费服务所产生的风险由您自行承担，我们不对服务使用的结果作出任何保证。</li></ul><h2 id="九、其他条款" tabindex="-1">九、其他条款 <a class="header-anchor" href="#九、其他条款" aria-label="Permalink to &quot;九、其他条款&quot;">​</a></h2><ul><li>本协议的订立、效力、解释、履行及争议解决均适用中华人民共和国法律。</li><li>因本协议引起的任何争议，双方应首先通过友好协商解决；协商不成的，任何一方均有权向 Vilinko Studio 所在地有管辖权的人民法院提起诉讼。</li><li>我们有权根据法律法规变化或业务需要修改本协议，修改后的协议将在公布后生效。您继续使用付费服务即表示接受修改后的协议。</li><li>如对本协议有任何疑问，可通过 <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a> 与我们联系。</li></ul><h2 id="第三方政策链接" tabindex="-1">第三方政策链接 <a class="header-anchor" href="#第三方政策链接" aria-label="Permalink to &quot;第三方政策链接&quot;">​</a></h2><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">爱发电平台服务条款</a></li></ul>',23)]))}const q=l(o,[["render",r]]);export{m as __pageData,q as default};
